WITH valid AS (SELECT *, LOWER(txn_type) AS txn_type_lower FROM transactions WHERE txn_time >= TO_DATE('2023-10-01') AND merchant IS NOT NULL), valid_transactions AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, txn_type_lower, INITCAP(TRIM(merchant)) AS merchant_title, INITCAP(TRIM(txn_type)) AS txn_type_title FROM valid WHERE txn_time >= TIMESTAMP '2024-05-12 06:00:00' AND merchant IS NOT NULL AND merchant IN ('Shell', 'Lazada')), flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM valid_transactions), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged), metrics AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, txn_type_lower, merchant_title, txn_type_title, is_new_session, session_no, ROW_NUMBER() OVER (PARTITION BY merchant, account_id ORDER BY txn_time DESC, id) AS event_seq, SUM(is_new_session) OVER (PARTITION BY merchant ORDER BY is_new_session, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_is_new_session, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY session_no, id) AS seq_no FROM sessions_transactions) SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, txn_type_lower, merchant_title, session_no, CASE WHEN merchant RLIKE '^(Grab|7-Eleven)$' THEN 'OTHER_ZONE' WHEN merchant RLIKE '^(Amazon|Lazada)$' THEN 'GROUP_B' ELSE 'CORE' END AS merchant_zone FROM metrics ORDER BY account_id DESC, merchant_zone
